-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (6173, 7, 'Rentenniveau gesetzlich bei mindestens 48 Prozent halten', 'Eine Haltelinie verhindert, dass die Renten wegen des steigenden Verhältnisses von Rentnern zu Beitragszahlenden hinter den Löhnen zurückfallen; das Missverhältnis bleibt, die Kosten steigen über Beiträge oder Steuerzuschüsse. Per Bundesgesetz umsetzbar, die dauerhafte Finanzierung ist offen.', 'gemischt', null, 'bund', null, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die Verlängerung der Haltelinie führt laut Deutscher Rentenversicherung ab 2032 zu jährlich knapp 12 Mrd. Euro Mehrausgaben, die der Bund erstatten soll.","quelle_url":"https://www.deutsche-rentenversicherung.de/DRV/DE/Ueber-uns-und-Presse/Presse/Pressemitteilungen/Pressemitteilungen-archiv/2025/2025-12-10-bvv-gunkel","belegstufe":"A"}]'::jsonb),
  (6174, 7, 'Anreize, über das Rentenalter hinaus zu arbeiten', 'Mehr Weiterarbeit im Rentenalter bringt der Rentenversicherung etwas mehr Beiträge und Steuern; Studien erwarten nur kleine Beschäftigungseffekte, Steuerfreiheit kostet Einnahmen. Per Bundesgesetz umsetzbar.', 'gemischt', null, 'bund', null, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die steuerfreie Weiterarbeit im Rentenalter entlastet die Beschäftigten laut Bundesregierung um bis zu 890 Mio. Euro jährlich; in dieser Höhe sinken die Steuereinnahmen.","quelle_url":"https://www.bundestag.de/dokumente/textarchiv/2025/kw46-de-aktivrente-1123118","belegstufe":"A"},{"bereich":"verteilung","richtung":"gemischt","text":"Die Aktivrente entlastet laut DIW vor allem Besserverdienende im Rentenalter; Minijobbende, rund 645.000 Personen, profitieren nicht von der Steuerfreiheit.","quelle_url":"https://www.diw.de/de/diw_01.c.959970.de/aktivrente_entlastet_vor_allem_besserverdienende_rentner_innen.html","belegstufe":"B"}]'::jsonb),
  (6175, 7, 'Pflicht zur Altersvorsorge für nicht abgesicherte Selbstständige', 'Viele Solo-Selbstständige sorgen kaum vor und sind im Alter häufiger arm; eine Vorsorgepflicht setzt direkt an dieser Lücke an, wirkt aber erst über Jahrzehnte, und Pflichtbeiträge belasten Selbstständige mit geringem Einkommen. Per Bundesgesetz umsetzbar.', 'gemischt', null, 'bund', null, true, null, '[]'::jsonb),
  (6176, 7, 'Beamte, Abgeordnete und weitere Gruppen in die gesetzliche Rente einbeziehen', 'Mehr Einzahlende verbessern das Verhältnis zu den Rentnern zunächst, später entstehen aus den Beiträgen aber auch Ansprüche; für Beamte kostet der Übergang Bund und Länder anfangs viel Geld. Per Bundesgesetz möglich, mit langen Übergangszeiten.', 'gemischt', null, 'bund', null, true, null, '[]'::jsonb),
  (6177, 7, 'Betriebsrenten stärker fördern und für kleine Betriebe erleichtern', 'Setzt direkt an der geringen Verbreitung von Betriebsrenten an; mehr Förderung und weniger Haftungsrisiken haben die Verbreitung bisher aber nur langsam erhöht, vor allem in kleinen Betrieben und bei Geringverdienenden. Per Bundesgesetz umsetzbar.', 'gemischt', null, 'bund', null, true, null, '[]'::jsonb),
  (6178, 7, 'Geförderte private Vorsorge neu ordnen (kostengünstige Depots, gezielte Förderung)', 'Kostengünstige, einfache Produkte und eine Förderung für kleine und mittlere Einkommen setzen an der Lücke bei der Zusatzvorsorge an; ob deutlich mehr Menschen vorsorgen, ist offen, solange die Teilnahme freiwillig bleibt. Per Bundesgesetz umsetzbar.', 'gemischt', null, 'bund', null, true, null, '[]'::jsonb),
  (6179, 7, 'Kapitalstock zur Stützung der gesetzlichen Rente', 'Ein Fonds kann den Beitragsanstieg dämpfen, wenn weniger Beitragszahlende auf mehr Rentner kommen; bei den vorgeschlagenen Größenordnungen ist der Effekt klein, die Erträge sind unsicher. Per Bundesgesetz umsetzbar, bei Kreditfinanzierung mit Haushaltsrisiken.', 'gemischt', null, 'bund', null, true, null, '[]'::jsonb),
  (6180, 7, 'Grundrente ausbauen, niedrige Rentenansprüche aufwerten', 'Eine stärkere Aufwertung niedriger Ansprüche setzt direkt an niedrigen Renten nach niedrigen Löhnen an; wer große Lücken im Erwerbsleben hat, profitiert oft nicht, die Kosten steigen. Per Bundesgesetz umsetzbar, die Finanzierung ist nicht geklärt.', 'gemischt', null, 'bund', null, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Die Einführung der Grundrente kostete laut Gesetzentwurf 2021 rund 1,3 Mrd. Euro; der Bundeszuschuss sollte dauerhaft um 1,4 Mrd. Euro steigen.","quelle_url":"https://www.bundestag.de/webarchiv/Ausschuesse/ausschuesse19/a11/Anhoerungen/683366-683366","belegstufe":"A"},{"bereich":"aufwand","richtung":"nachteil","text":"Zum Vergleich: Die Rentenversicherung nannte die Einkommensprüfung der Grundrente trotz Datenaustausch ''mit einem hohen Bürokratieaufwand verbunden'' und nannte 1.700 Stellen.","quelle_url":"https://www.bundestag.de/webarchiv/Ausschuesse/ausschuesse19/a11/Anhoerungen/683366-683366","belegstufe":"A"},{"bereich":"verteilung","richtung":"gemischt","text":"Zum Vergleich: Bei der bestehenden Grundrente gingen Ende 2024 rund 76 % der Zuschläge an Frauen; rund die Hälfte der Berechtigten erhielt wegen zu hoher Haushaltseinkommen nichts.","quelle_url":"https://www.diw.de/de/diw_01.c.981265.de/publikationen/wochenberichte/2025_41_1/grundrentenberechtigte_haeufiger_erwerbstaetig_als_andere_rentner_innen.html","belegstufe":"B"}]'::jsonb),
  (6181, 7, 'Mindestlohn auf mindestens 15 Euro anheben', 'Ein höherer Mindestlohn erhöht die Rentenansprüche von Geringverdienenden; auch mit 15 Euro liegt die Rente nach Lücken im Erwerbsleben oft nahe der Grundsicherung. Per Bundesgesetz umsetzbar, bisher entscheidet die Mindestlohnkommission.', 'gemischt', null, 'bund', null, true, null, '[{"bereich":"wirtschaft","richtung":"nachteil","text":"Auf höhere Lohnkosten reagierten nach der Anhebung auf 12 Euro (2022) 53,4 % der Mindestlohnbetriebe und 72,6 % im Gastgewerbe mit Preiserhöhungen (IAB-Betriebsbefragung).","quelle_url":"https://iab-forum.de/mindestlohnerhoehung-auf-12-euro-nur-wenige-betriebe-reagierten-eigenen-angaben-zufolge-mit-entlassungen/","belegstufe":"B"},{"bereich":"verteilung","richtung":"vorteil","text":"Von der Anhebung auf 13,90 Euro waren laut Destatis rund 20 % der Jobs von Frauen betroffen (Männer 14 %), in Ostdeutschland rund 20 % (Westdeutschland 16 %).","quelle_url":"https://www.destatis.de/DE/Presse/Pressemitteilungen/2025/07/PD25_256_62.html","belegstufe":"A"}]'::jsonb),
  (6182, 7, 'Nicht beitragsgedeckte Leistungen aus dem Bundeshaushalt finanzieren', 'Verlagert Kosten von den Beitragszahlenden auf die Steuerzahlenden und entlastet die Beiträge; am Verhältnis von Beitragszahlenden zu Rentnern ändert es nichts. Es geht um zweistellige Milliardenbeträge im Jahr, deren Finanzierung offen ist.', 'gemischt', null, 'bund', null, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Laut DRV-Schätzung hätten die Bundeszuschüsse 2023 rund 40 Mrd. Euro höher sein müssen, um die nicht beitragsgedeckten Leistungen zu decken (rund 124 statt 84 Mrd. Euro).","quelle_url":"https://rentenupdate.drv-bund.de/DE/1_Archiv/Archiv/2025/10_Bundeszuschuesse_nbL?nn=69daab5139cdab02f5c5d350","belegstufe":"A"}]'::jsonb)
