insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (6183, 7, 11, null, 'Aktivrente: Arbeitslohn nach Erreichen der Regelaltersgrenze bis 2.000 Euro im Monat steuerfrei', '{701}', 6174, 1, 3, null, 'Mehr Weiterarbeit im Rentenalter bringt der Rentenversicherung etwas mehr Beiträge und Steuern; Studien erwarten nur kleine Beschäftigungseffekte, Steuerfreiheit kostet Einnahmen. Per Bundesgesetz umsetzbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=35', null, 'gemischt', '2026-09-29', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die steuerfreie Weiterarbeit im Rentenalter entlastet die Beschäftigten laut Bundesregierung um bis zu 890 Mio. Euro jährlich; in dieser Höhe sinken die Steuereinnahmen.","quelle_url":"https://www.bundestag.de/dokumente/textarchiv/2025/kw46-de-aktivrente-1123118","belegstufe":"A"},{"bereich":"verteilung","richtung":"gemischt","text":"Die Aktivrente entlastet laut DIW vor allem Besserverdienende im Rentenalter; Minijobbende, rund 645.000 Personen, profitieren nicht von der Steuerfreiheit.","quelle_url":"https://www.diw.de/de/diw_01.c.959970.de/aktivrente_entlastet_vor_allem_besserverdienende_rentner_innen.html","belegstufe":"B"}]'::jsonb),
  (6184, 7, 11, null, 'Kleine und mittlere Arbeitgeber beim Abschluss von Betriebsrenten unterstützen', '{703}', 6177, 2, 3, null, 'Setzt direkt an der geringen Verbreitung von Betriebsrenten an; mehr Förderung und weniger Haftungsrisiken haben die Verbreitung bisher aber nur langsam erhöht, vor allem in kleinen Betrieben und bei Geringverdienenden. Per Bundesgesetz umsetzbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=35', null, 'gemischt', '2026-09-29', false, true, null, '[]'::jsonb),
  (6185, 7, 11, null, 'Frühstart-Rente: 10 Euro im Monat vom 6. bis 18. Lebensjahr in ein kapitalgedecktes Altersvorsorgedepot', '{703}', null, 1, 3, null, '10 Euro im Monat ergeben bis zum Rentenalter nur einen kleinen Zusatzbetrag, und die Wirkung setzt erst in Jahrzehnten ein; das Depot kann aber den Einstieg in eigene Vorsorge erleichtern. Per Bundesgesetz umsetzbar, die Kosten sind überschaubar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=35', null, 'gemischt', '2026-09-29', false, true, null, '[]'::jsonb),
  (6186, 7, 11, null, 'Verbindliche Altersvorsorge für nicht ausreichend abgesicherte Selbstständige', '{702}', 6175, 2, 3, null, 'Viele Solo-Selbstständige sorgen kaum vor und sind im Alter häufiger arm; eine Vorsorgepflicht setzt direkt an dieser Lücke an, wirkt aber erst über Jahrzehnte, und Pflichtbeiträge belasten Selbstständige mit geringem Einkommen. Per Bundesgesetz umsetzbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=35', null, 'gemischt', '2026-09-29', false, true, null, '[]'::jsonb),
  (6187, 7, 12, null, 'Rentenniveau dauerhaft bei mindestens 48 Prozent sichern', '{701}', 6173, 1, 2, null, 'Eine Haltelinie verhindert, dass die Renten wegen des steigenden Verhältnisses von Rentnern zu Beitragszahlenden hinter den Löhnen zurückfallen; das Missverhältnis bleibt, die Kosten steigen über Beiträge oder Steuerzuschüsse. Per Bundesgesetz umsetzbar, die dauerhafte Finanzierung ist offen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=25', null, 'gemischt', '2026-09-29', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die Verlängerung der Haltelinie führt laut Deutscher Rentenversicherung ab 2032 zu jährlich knapp 12 Mrd. Euro Mehrausgaben, die der Bund erstatten soll.","quelle_url":"https://www.deutsche-rentenversicherung.de/DRV/DE/Ueber-uns-und-Presse/Presse/Pressemitteilungen/Pressemitteilungen-archiv/2025/2025-12-10-bvv-gunkel","belegstufe":"A"}]'::jsonb),
  (6188, 7, 12, null, 'Weiterarbeit nach Rentenbeginn: Arbeitgeberbeiträge an die Beschäftigten auszahlen', '{701}', 6174, 1, 3, null, 'Mehr Weiterarbeit im Rentenalter bringt der Rentenversicherung etwas mehr Beiträge und Steuern; Studien erwarten nur kleine Beschäftigungseffekte, Steuerfreiheit kostet Einnahmen. Per Bundesgesetz umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=25', null, 'gemischt', '2026-09-29', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die steuerfreie Weiterarbeit im Rentenalter entlastet die Beschäftigten laut Bundesregierung um bis zu 890 Mio. Euro jährlich; in dieser Höhe sinken die Steuereinnahmen.","quelle_url":"https://www.bundestag.de/dokumente/textarchiv/2025/kw46-de-aktivrente-1123118","belegstufe":"A"},{"bereich":"verteilung","richtung":"gemischt","text":"Die Aktivrente entlastet laut DIW vor allem Besserverdienende im Rentenalter; Minijobbende, rund 645.000 Personen, profitieren nicht von der Steuerfreiheit.","quelle_url":"https://www.diw.de/de/diw_01.c.959970.de/aktivrente_entlastet_vor_allem_besserverdienende_rentner_innen.html","belegstufe":"B"}]'::jsonb),
  (6189, 7, 12, null, 'Langfristig alle Erwerbstätigen in die gesetzliche Rente einbeziehen', '{701}', 6176, 1, 2, null, 'Mehr Einzahlende verbessern das Verhältnis zu den Rentnern zunächst, später entstehen aus den Beiträgen aber auch Ansprüche; für Beamte kostet der Übergang Bund und Länder anfangs viel Geld. Per Bundesgesetz möglich, mit langen Übergangszeiten.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=25', null, 'gemischt', '2026-09-29', false, true, null, '[]'::jsonb),
  (6190, 7, 12, null, 'Zunächst alle Selbstständigen absichern', '{702}', 6175, 2, 3, null, 'Viele Solo-Selbstständige sorgen kaum vor und sind im Alter häufiger arm; eine Vorsorgepflicht setzt direkt an dieser Lücke an, wirkt aber erst über Jahrzehnte, und Pflichtbeiträge belasten Selbstständige mit geringem Einkommen. Per Bundesgesetz umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=25', null, 'gemischt', '2026-09-29', false, true, null, '[]'::jsonb),
  (6191, 7, 12, null, 'Steuerliche Förderung der Betriebsrente für Geringverdiener ausbauen', '{703}', 6177, 2, 3, null, 'Setzt direkt an der geringen Verbreitung von Betriebsrenten an; mehr Förderung und weniger Haftungsrisiken haben die Verbreitung bisher aber nur langsam erhöht, vor allem in kleinen Betrieben und bei Geringverdienenden. Per Bundesgesetz umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=25', null, 'gemischt', '2026-09-29', false, true, null, '[]'::jsonb),
  (6192, 7, 12, null, 'Förderung privater Vorsorge nur für Produkte mit gedeckelten Kosten, konzentriert auf kleine und mittlere Einkommen', '{703}', 6178, 2, 3, null, 'Kostengünstige, einfache Produkte und eine Förderung für kleine und mittlere Einkommen setzen an der Lücke bei der Zusatzvorsorge an; ob deutlich mehr Menschen vorsorgen, ist offen, solange die Teilnahme freiwillig bleibt. Per Bundesgesetz umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=25', null, 'gemischt', '2026-09-29', false, true, null, '[]'::jsonb),
  (6193, 7, 12, null, 'Mindestlohn spätestens 2026 auf 15 Euro', '{702}', 6181, 1, 3, null, 'Ein höherer Mindestlohn erhöht die Rentenansprüche von Geringverdienenden; auch mit 15 Euro liegt die Rente nach Lücken im Erwerbsleben oft nahe der Grundsicherung. Per Bundesgesetz umsetzbar, bisher entscheidet die Mindestlohnkommission.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=23', null, 'gemischt', '2026-09-29', false, true, null, '[{"bereich":"wirtschaft","richtung":"nachteil","text":"Auf höhere Lohnkosten reagierten nach der Anhebung auf 12 Euro (2022) 53,4 % der Mindestlohnbetriebe und 72,6 % im Gastgewerbe mit Preiserhöhungen (IAB-Betriebsbefragung).","quelle_url":"https://iab-forum.de/mindestlohnerhoehung-auf-12-euro-nur-wenige-betriebe-reagierten-eigenen-angaben-zufolge-mit-entlassungen/","belegstufe":"B"},{"bereich":"verteilung","richtung":"vorteil","text":"Von der Anhebung auf 13,90 Euro waren laut Destatis rund 20 % der Jobs von Frauen betroffen (Männer 14 %), in Ostdeutschland rund 20 % (Westdeutschland 16 %).","quelle_url":"https://www.destatis.de/DE/Presse/Pressemitteilungen/2025/07/PD25_256_62.html","belegstufe":"A"}]'::jsonb),
  (6194, 7, 13, null, 'Rentenniveau bei mindestens 48 Prozent halten', '{701}', 6173, 1, 2, null, 'Eine Haltelinie verhindert, dass die Renten wegen des steigenden Verhältnisses von Rentnern zu Beitragszahlenden hinter den Löhnen zurückfallen; das Missverhältnis bleibt, die Kosten steigen über Beiträge oder Steuerzuschüsse. Per Bundesgesetz umsetzbar, die dauerhafte Finanzierung ist offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=97', null, 'gemischt', '2026-09-29', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die Verlängerung der Haltelinie führt laut Deutscher Rentenversicherung ab 2032 zu jährlich knapp 12 Mrd. Euro Mehrausgaben, die der Bund erstatten soll.","quelle_url":"https://www.deutsche-rentenversicherung.de/DRV/DE/Ueber-uns-und-Presse/Presse/Pressemitteilungen/Pressemitteilungen-archiv/2025/2025-12-10-bvv-gunkel","belegstufe":"A"}]'::jsonb),
  (6195, 7, 13, null, 'Grundrente zu einer Garantierente nach 30 Versicherungsjahren weiterentwickeln', '{702}', 6180, 2, 2, null, 'Eine stärkere Aufwertung niedriger Ansprüche setzt direkt an niedrigen Renten nach niedrigen Löhnen an; wer große Lücken im Erwerbsleben hat, profitiert oft nicht, die Kosten steigen. Per Bundesgesetz umsetzbar, die Finanzierung ist nicht geklärt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=97', null, 'gemischt', '2026-09-29', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Die Einführung der Grundrente kostete laut Gesetzentwurf 2021 rund 1,3 Mrd. Euro; der Bundeszuschuss sollte dauerhaft um 1,4 Mrd. Euro steigen.","quelle_url":"https://www.bundestag.de/webarchiv/Ausschuesse/ausschuesse19/a11/Anhoerungen/683366-683366","belegstufe":"A"},{"bereich":"aufwand","richtung":"nachteil","text":"Zum Vergleich: Die Rentenversicherung nannte die Einkommensprüfung der Grundrente trotz Datenaustausch ''mit einem hohen Bürokratieaufwand verbunden'' und nannte 1.700 Stellen.","quelle_url":"https://www.bundestag.de/webarchiv/Ausschuesse/ausschuesse19/a11/Anhoerungen/683366-683366","belegstufe":"A"},{"bereich":"verteilung","richtung":"gemischt","text":"Zum Vergleich: Bei der bestehenden Grundrente gingen Ende 2024 rund 76 % der Zuschläge an Frauen; rund die Hälfte der Berechtigten erhielt wegen zu hoher Haushaltseinkommen nichts.","quelle_url":"https://www.diw.de/de/diw_01.c.981265.de/publikationen/wochenberichte/2025_41_1/grundrentenberechtigte_haeufiger_erwerbstaetig_als_andere_rentner_innen.html","belegstufe":"B"}]'::jsonb),
  (6196, 7, 13, null, 'Mehr Beitragszahlende durch höhere Erwerbstätigkeit von Frauen und qualifizierte Zuwanderung', '{701}', null, 2, 2, null, 'Eine höhere Erwerbstätigkeit, vor allem von Frauen, und Zuwanderung in Arbeit gelten in Studien als wichtigste Hebel gegen das sinkende Verhältnis von Beitragszahlenden zu Rentnern; das Programm nennt aber keine Größenordnung. Kitaausbau und Integration brauchen Länder, Kommunen und Zeit.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=97', null, 'belegt', '2026-09-29', false, true, null, '[{"bereich":"wirtschaft","richtung":"vorteil","text":"Laut IAB braucht es rund 400.000 Personen Nettozuwanderung pro Jahr, um das Erwerbspersonenpotenzial konstant zu halten; inländische Mobilisierung bringt nur 1,5-1,8 Mio.","quelle_url":"https://iab-forum.de/bei-der-arbeitskraeftesicherung-gilt-es-jeden-hebel-zu-nutzen/","belegstufe":"B"}]'::jsonb),
  (6197, 7, 13, null, 'Mindestlohn erneut anheben, Minijobs abbauen', '{702}', 6181, 1, 3, null, 'Ein höherer Mindestlohn erhöht die Rentenansprüche von Geringverdienenden; auch mit 15 Euro liegt die Rente nach Lücken im Erwerbsleben oft nahe der Grundsicherung. Per Bundesgesetz umsetzbar, bisher entscheidet die Mindestlohnkommission.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=98', null, 'gemischt', '2026-09-29', false, true, null, '[{"bereich":"wirtschaft","richtung":"nachteil","text":"Auf höhere Lohnkosten reagierten nach der Anhebung auf 12 Euro (2022) 53,4 % der Mindestlohnbetriebe und 72,6 % im Gastgewerbe mit Preiserhöhungen (IAB-Betriebsbefragung).","quelle_url":"https://iab-forum.de/mindestlohnerhoehung-auf-12-euro-nur-wenige-betriebe-reagierten-eigenen-angaben-zufolge-mit-entlassungen/","belegstufe":"B"},{"bereich":"verteilung","richtung":"vorteil","text":"Von der Anhebung auf 13,90 Euro waren laut Destatis rund 20 % der Jobs von Frauen betroffen (Männer 14 %), in Ostdeutschland rund 20 % (Westdeutschland 16 %).","quelle_url":"https://www.destatis.de/DE/Presse/Pressemitteilungen/2025/07/PD25_256_62.html","belegstufe":"A"}]'::jsonb),
  (6198, 7, 13, null, 'Gesetzliche Rente zur Bürgerversicherung: Abgeordnete und perspektivisch Beamte einbeziehen', '{701}', 6176, 1, 2, null, 'Mehr Einzahlende verbessern das Verhältnis zu den Rentnern zunächst, später entstehen aus den Beiträgen aber auch Ansprüche; für Beamte kostet der Übergang Bund und Länder anfangs viel Geld. Per Bundesgesetz möglich, mit langen Übergangszeiten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=98', null, 'gemischt', '2026-09-29', false, true, null, '[]'::jsonb),
  (6199, 7, 13, null, 'Nicht anderweitig abgesicherte Selbstständige einbeziehen', '{702}', 6175, 2, 3, null, 'Viele Solo-Selbstständige sorgen kaum vor und sind im Alter häufiger arm; eine Vorsorgepflicht setzt direkt an dieser Lücke an, wirkt aber erst über Jahrzehnte, und Pflichtbeiträge belasten Selbstständige mit geringem Einkommen. Per Bundesgesetz umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=98', null, 'gemischt', '2026-09-29', false, true, null, '[]'::jsonb),
  (6200, 7, 13, null, 'Weiterarbeit neben dem Rentenbezug: Arbeitgeberbeiträge an die Beschäftigten auszahlen', '{701}', 6174, 1, 3, null, 'Mehr Weiterarbeit im Rentenalter bringt der Rentenversicherung etwas mehr Beiträge und Steuern; Studien erwarten nur kleine Beschäftigungseffekte, Steuerfreiheit kostet Einnahmen. Per Bundesgesetz umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=98', null, 'gemischt', '2026-09-29', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die steuerfreie Weiterarbeit im Rentenalter entlastet die Beschäftigten laut Bundesregierung um bis zu 890 Mio. Euro jährlich; in dieser Höhe sinken die Steuereinnahmen.","quelle_url":"https://www.bundestag.de/dokumente/textarchiv/2025/kw46-de-aktivrente-1123118","belegstufe":"A"},{"bereich":"verteilung","richtung":"gemischt","text":"Die Aktivrente entlastet laut DIW vor allem Besserverdienende im Rentenalter; Minijobbende, rund 645.000 Personen, profitieren nicht von der Steuerfreiheit.","quelle_url":"https://www.diw.de/de/diw_01.c.959970.de/aktivrente_entlastet_vor_allem_besserverdienende_rentner_innen.html","belegstufe":"B"}]'::jsonb),
  (6201, 7, 13, null, 'Ergänzende Kapitaldeckung in der gesetzlichen Rente aus Bundesmitteln (Bürger*innenfonds)', '{701}', 6179, 1, 2, null, 'Ein Fonds kann den Beitragsanstieg dämpfen, wenn weniger Beitragszahlende auf mehr Rentner kommen; bei den vorgeschlagenen Größenordnungen ist der Effekt klein, die Erträge sind unsicher. Per Bundesgesetz umsetzbar, bei Kreditfinanzierung mit Haushaltsrisiken.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=98', null, 'gemischt', '2026-09-29', false, true, null, '[]'::jsonb),
  (6202, 7, 13, null, 'Öffentlich verwalteter Bürger*innenfonds für die private Vorsorge mit Widerspruchslösung', '{703}', null, 2, 2, null, 'Automatische Teilnahme mit Widerspruchsrecht hat in Großbritannien und Neuseeland die Beteiligung an Zusatzvorsorge stark erhöht; wie hoch die Zusatzrente wird, hängt von den Beiträgen ab. Der öffentliche Fonds muss erst aufgebaut werden.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=98', null, 'belegt', '2026-09-29', false, true, null, '[]'::jsonb),
  (6203, 7, 13, null, 'Bürger*innenfonds auch für Betriebsrenten öffnen, vor allem für kleine und mittlere Unternehmen', '{703}', 6177, 2, 3, null, 'Setzt direkt an der geringen Verbreitung von Betriebsrenten an; mehr Förderung und weniger Haftungsrisiken haben die Verbreitung bisher aber nur langsam erhöht, vor allem in kleinen Betrieben und bei Geringverdienenden. Per Bundesgesetz umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=99', null, 'gemischt', '2026-09-29', false, true, null, '[]'::jsonb),
  (6204, 7, 14, null, 'Flexibler Renteneintritt nach schwedischem Vorbild mit Zu- und Abschlägen', '{701}', null, 1, 3, null, 'Ein flexibler Renteneintritt mit fairen Zu- und Abschlägen kann längeres Arbeiten attraktiver machen; wie viele dadurch später in Rente gehen, ist unsicher, wer früher geht, bekommt weniger. Per Bundesgesetz umsetzbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=21', null, 'gemischt', '2026-09-29', false, true, null, '[]'::jsonb),
  (6205, 7, 14, null, 'Gesetzliche Aktienrente: kleiner Teil der Rentenbeiträge in einen unabhängig verwalteten Fonds', '{701}', 6179, 1, 2, null, 'Ein Fonds kann den Beitragsanstieg dämpfen, wenn weniger Beitragszahlende auf mehr Rentner kommen; bei den vorgeschlagenen Größenordnungen ist der Effekt klein, die Erträge sind unsicher. Per Bundesgesetz umsetzbar, bei Kreditfinanzierung mit Haushaltsrisiken.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=21', null, 'gemischt', '2026-09-29', false, true, null, '[]'::jsonb),
  (6206, 7, 14, null, 'Steuerlich gefördertes Altersvorsorgedepot für die private Vorsorge', '{703}', 6178, 2, 3, null, 'Kostengünstige, einfache Produkte und eine Förderung für kleine und mittlere Einkommen setzen an der Lücke bei der Zusatzvorsorge an; ob deutlich mehr Menschen vorsorgen, ist offen, solange die Teilnahme freiwillig bleibt. Per Bundesgesetz umsetzbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=21', null, 'gemischt', '2026-09-29', false, true, null, '[]'::jsonb),
  (6207, 7, 14, null, 'Reine Beitragszusage allen Betrieben ermöglichen, vor allem Kleinstbetrieben', '{703}', 6177, 2, 3, null, 'Setzt direkt an der geringen Verbreitung von Betriebsrenten an; mehr Förderung und weniger Haftungsrisiken haben die Verbreitung bisher aber nur langsam erhöht, vor allem in kleinen Betrieben und bei Geringverdienenden. Per Bundesgesetz umsetzbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=21', null, 'gemischt', '2026-09-29', false, true, null, '[]'::jsonb),
  (6208, 7, 15, null, 'Verbeamtung nur für Hoheitsaufgaben, Politiker in die gesetzliche Rente', '{701}', 6176, 1, 2, null, 'Mehr Einzahlende verbessern das Verhältnis zu den Rentnern zunächst, später entstehen aus den Beiträgen aber auch Ansprüche; für Beamte kostet der Übergang Bund und Länder anfangs viel Geld. Per Bundesgesetz möglich, mit langen Übergangszeiten.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=19', null, 'gemischt', '2026-09-29', false, true, null, '[]'::jsonb),
  (6209, 7, 15, null, 'Alle nicht beitragsgedeckten Leistungen aus dem Bundeshaushalt finanzieren', '{701}', 6182, 1, 1, null, 'Verlagert Kosten von den Beitragszahlenden auf die Steuerzahlenden und entlastet die Beiträge; am Verhältnis von Beitragszahlenden zu Rentnern ändert es nichts. Es geht um zweistellige Milliardenbeträge im Jahr, deren Finanzierung offen ist.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=19', null, 'gemischt', '2026-09-29', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Laut DRV-Schätzung hätten die Bundeszuschüsse 2023 rund 40 Mrd. Euro höher sein müssen, um die nicht beitragsgedeckten Leistungen zu decken (rund 124 statt 84 Mrd. Euro).","quelle_url":"https://rentenupdate.drv-bund.de/DE/1_Archiv/Archiv/2025/10_Bundeszuschuesse_nbL?nn=69daab5139cdab02f5c5d350","belegstufe":"A"}]'::jsonb),
  (6210, 7, 15, null, 'Elternschaft in der Rente höher bewerten', '{702}', null, 1, 2, null, 'Höhere Rentenansprüche für Eltern gleichen Lücken im Erwerbsleben durch Kindererziehung teilweise aus; das Programm nennt weder Umfang noch Finanzierung. Per Bundesgesetz umsetzbar, zuletzt bei der Mütterrente mit hohen Kosten.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=20', null, 'gemischt', '2026-09-29', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Die Mütterrente III kostet laut Rentenversicherung rund 5 Mrd. Euro pro Jahr und soll aus Steuermitteln statt aus Beiträgen finanziert werden.","quelle_url":"https://www.deutsche-rentenversicherung.de/DRV/DE/Ueber-uns-und-Presse/Presse/Meldungen/2025/250806-statement-rentenpaket-muetterrente-III.html","belegstufe":"A"},{"bereich":"grundrechte","richtung":"gemischt","text":"Zum Vergleich: Angerechnete Kindererziehungszeiten verkleinern die Rentenlücke zwischen Frauen und Männern in Westdeutschland (Jahrgänge 1952 bis 1959) laut DIW nur von 41 auf 37 %.","quelle_url":"https://www.diw.de/de/diw_01.c.941727.de/angerechnete_kindererziehungszeiten_verkleinern_rentenluecke_zwischen_frauen_und_maennern_nur_geringfuegig.html","belegstufe":"B"}]'::jsonb),
  (6211, 7, 15, null, 'Private und betriebliche Vorsorge mit Aktien, ETFs und Fonds systematisch steuerlich fördern', '{703}', 6178, 2, 3, null, 'Kostengünstige, einfache Produkte und eine Förderung für kleine und mittlere Einkommen setzen an der Lücke bei der Zusatzvorsorge an; ob deutlich mehr Menschen vorsorgen, ist offen, solange die Teilnahme freiwillig bleibt. Per Bundesgesetz umsetzbar.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=20', null, 'gemischt', '2026-09-29', false, true, null, '[]'::jsonb),
  (6212, 7, 15, null, 'Junior-Spardepot: 100 Euro im Monat aus Steuermitteln bis zum 18. Lebensjahr für jedes Kind mit deutscher Staatsangehörigkeit', '{703}', null, 2, 1, null, '100 Euro im Monat über 18 Jahre ergeben einen spürbaren Kapitalstock für das Alter; die Kosten von grob 15 Milliarden Euro im Jahr sind nicht gegenfinanziert, und die Beschränkung auf deutsche Kinder ist verfassungsrechtlich fraglich.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=20', null, 'offen', '2026-09-29', false, true, null, '[]'::jsonb),
  (6213, 7, 15, null, 'Zusätzlicher Steuerfreibetrag von 12.000 Euro für arbeitende Rentner', '{701}', 6174, 1, 3, null, 'Mehr Weiterarbeit im Rentenalter bringt der Rentenversicherung etwas mehr Beiträge und Steuern; Studien erwarten nur kleine Beschäftigungseffekte, Steuerfreiheit kostet Einnahmen. Per Bundesgesetz umsetzbar.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=21', null, 'gemischt', '2026-09-29', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die steuerfreie Weiterarbeit im Rentenalter entlastet die Beschäftigten laut Bundesregierung um bis zu 890 Mio. Euro jährlich; in dieser Höhe sinken die Steuereinnahmen.","quelle_url":"https://www.bundestag.de/dokumente/textarchiv/2025/kw46-de-aktivrente-1123118","belegstufe":"A"},{"bereich":"verteilung","richtung":"gemischt","text":"Die Aktivrente entlastet laut DIW vor allem Besserverdienende im Rentenalter; Minijobbende, rund 645.000 Personen, profitieren nicht von der Steuerfreiheit.","quelle_url":"https://www.diw.de/de/diw_01.c.959970.de/aktivrente_entlastet_vor_allem_besserverdienende_rentner_innen.html","belegstufe":"B"}]'::jsonb),
  (6214, 7, 15, null, 'Mehr Erwerbsanreize durch niedrigere Einkommensteuern und ein weniger attraktives Bürgergeld', '{701}', null, 1, 2, null, 'Stärkere Arbeitsanreize können die Zahl der Beitragszahlenden etwas erhöhen; wie stark Steuersenkungen und Kürzungen beim Bürgergeld die Beschäftigung steigern, ist in der Forschung umstritten. Steuersenkungen sind nicht gegenfinanziert.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=21', null, 'gemischt', '2026-09-29', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Die Einkommensteuerreform 2027 hat laut Bundesregierung ein Entlastungsvolumen von rund 10 Mrd. Euro im Jahr, was entsprechend geringere Steuereinnahmen bedeutet.","quelle_url":"https://www.bundesregierung.de/breg-de/aktuelles/einkommensteuerreform-2027-2451192","belegstufe":"A"}]'::jsonb),
  (6215, 7, 15, null, 'Willkommensprämie von 20.000 Euro für jedes neugeborene Kind', '{701}', null, 1, 1, null, 'Mehr Geburten würden das Verhältnis von Beitragszahlenden zu Rentnern erst nach rund zwei Jahrzehnten verbessern; ob Geldprämien die Geburtenrate dauerhaft erhöhen, ist umstritten. Die Kosten von rund 13 Milliarden Euro im Jahr sind nicht gegenfinanziert.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=21', null, 'gemischt', '2026-09-29', false, true, null, '[]'::jsonb),
  (6216, 7, 16, null, 'Solidarische Erwerbstätigenversicherung für alle mit Erwerbseinkommen', '{701}', 6176, 1, 2, null, 'Mehr Einzahlende verbessern das Verhältnis zu den Rentnern zunächst, später entstehen aus den Beiträgen aber auch Ansprüche; für Beamte kostet der Übergang Bund und Länder anfangs viel Geld. Per Bundesgesetz möglich, mit langen Übergangszeiten.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, 'gemischt', '2026-09-29', false, true, null, '[]'::jsonb),
  (6217, 7, 16, null, 'Rentenniveau auf 53 Prozent anheben', '{701}', null, 1, 1, null, 'Ein höheres Rentenniveau erhöht die Renten aller, gleicht aber nur die Folgen des steigenden Verhältnisses von Rentnern zu Beitragszahlenden aus; die Mehrkosten von jährlich deutlich über 30 Milliarden Euro sind nicht geklärt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, 'gemischt', '2026-09-29', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Die Haltelinie von 48 % kostet den Bund laut Gesetzentwurf 2029 rund 3,6 und 2031 rund 11,0 Mrd. Euro; ein höheres Rentenniveau würde mehr kosten.","quelle_url":"https://www.ihre-vorsorge.de/rente/nachrichten/stabiles-rentenniveau-kostet-alle-steuerzahler-milliarden-euro","belegstufe":"A"}]'::jsonb),
  (6218, 7, 16, null, 'Niedrige Rentenansprüche von Geringverdienenden, Erwerbslosen, Erziehenden und Pflegenden aufwerten', '{702}', 6180, 2, 2, null, 'Eine stärkere Aufwertung niedriger Ansprüche setzt direkt an niedrigen Renten nach niedrigen Löhnen an; wer große Lücken im Erwerbsleben hat, profitiert oft nicht, die Kosten steigen. Per Bundesgesetz umsetzbar, die Finanzierung ist nicht geklärt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, 'gemischt', '2026-09-29', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Die Einführung der Grundrente kostete laut Gesetzentwurf 2021 rund 1,3 Mrd. Euro; der Bundeszuschuss sollte dauerhaft um 1,4 Mrd. Euro steigen.","quelle_url":"https://www.bundestag.de/webarchiv/Ausschuesse/ausschuesse19/a11/Anhoerungen/683366-683366","belegstufe":"A"},{"bereich":"aufwand","richtung":"nachteil","text":"Zum Vergleich: Die Rentenversicherung nannte die Einkommensprüfung der Grundrente trotz Datenaustausch ''mit einem hohen Bürokratieaufwand verbunden'' und nannte 1.700 Stellen.","quelle_url":"https://www.bundestag.de/webarchiv/Ausschuesse/ausschuesse19/a11/Anhoerungen/683366-683366","belegstufe":"A"},{"bereich":"verteilung","richtung":"gemischt","text":"Zum Vergleich: Bei der bestehenden Grundrente gingen Ende 2024 rund 76 % der Zuschläge an Frauen; rund die Hälfte der Berechtigten erhielt wegen zu hoher Haushaltseinkommen nichts.","quelle_url":"https://www.diw.de/de/diw_01.c.981265.de/publikationen/wochenberichte/2025_41_1/grundrentenberechtigte_haeufiger_erwerbstaetig_als_andere_rentner_innen.html","belegstufe":"B"}]'::jsonb),
  (6219, 7, 16, null, 'Versicherungsfremde Leistungen nicht mehr aus Beiträgen finanzieren', '{701}', 6182, 1, 1, null, 'Verlagert Kosten von den Beitragszahlenden auf die Steuerzahlenden und entlastet die Beiträge; am Verhältnis von Beitragszahlenden zu Rentnern ändert es nichts. Es geht um zweistellige Milliardenbeträge im Jahr, deren Finanzierung offen ist.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, 'gemischt', '2026-09-29', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Laut DRV-Schätzung hätten die Bundeszuschüsse 2023 rund 40 Mrd. Euro höher sein müssen, um die nicht beitragsgedeckten Leistungen zu decken (rund 124 statt 84 Mrd. Euro).","quelle_url":"https://rentenupdate.drv-bund.de/DE/1_Archiv/Archiv/2025/10_Bundeszuschuesse_nbL?nn=69daab5139cdab02f5c5d350","belegstufe":"A"}]'::jsonb),
  (6220, 7, 16, null, 'Solidarische Mindestrente bis zur Armutsrisikogrenze (rund 1.400 Euro)', '{702}', null, 2, 1, null, 'Ein Zuschlag bis zur Armutsrisikogrenze beseitigt Altersarmut nach niedrigen Löhnen und Lücken direkt, setzt aber nicht an den Löhnen selbst an und kann den Anreiz zu eigener Vorsorge schwächen. Die Kosten wären hoch, die Finanzierung ist offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, 'gemischt', '2026-09-29', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Die Grundrente kostete laut Gesetzentwurf rund 1,3 Mrd. Euro im Einführungsjahr 2021 für rund 1,3 Mio. Menschen; ein Zuschlag bis zur Armutsrisikogrenze würde mehr kosten.","quelle_url":"https://www.bundestag.de/webarchiv/Ausschuesse/ausschuesse19/a11/Anhoerungen/683366-683366","belegstufe":"A"},{"bereich":"aufwand","richtung":"nachteil","text":"Zum Vergleich: Bei der Grundrente hielt die Rentenversicherung die Einkommensprüfung für mit hohem Bürokratieaufwand verbunden und nannte dafür 1.700 Stellen.","quelle_url":"https://www.bundestag.de/webarchiv/Ausschuesse/ausschuesse19/a11/Anhoerungen/683366-683366","belegstufe":"A"}]'::jsonb),
  (6221, 7, 16, null, 'Betriebsrenten mindestens zur Hälfte durch die Arbeitgeber finanzieren', '{703}', null, 1, 3, null, 'Ein Pflichtanteil der Arbeitgeber erhöht die Leistungen bestehender Betriebsrenten, bringt aber nicht mehr Betriebe dazu, überhaupt eine anzubieten, und könnte kleine Betriebe eher abschrecken. Per Bundesgesetz umsetzbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, 'gemischt', '2026-09-29', false, true, null, '[]'::jsonb),
  (6222, 7, 16, null, 'Mindestlohn von mindestens 15 Euro, ab 2026 16 Euro', '{702}', 6181, 1, 3, null, 'Ein höherer Mindestlohn erhöht die Rentenansprüche von Geringverdienenden; auch mit 15 Euro liegt die Rente nach Lücken im Erwerbsleben oft nahe der Grundsicherung. Per Bundesgesetz umsetzbar, bisher entscheidet die Mindestlohnkommission.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, 'gemischt', '2026-09-29', false, true, null, '[{"bereich":"wirtschaft","richtung":"nachteil","text":"Auf höhere Lohnkosten reagierten nach der Anhebung auf 12 Euro (2022) 53,4 % der Mindestlohnbetriebe und 72,6 % im Gastgewerbe mit Preiserhöhungen (IAB-Betriebsbefragung).","quelle_url":"https://iab-forum.de/mindestlohnerhoehung-auf-12-euro-nur-wenige-betriebe-reagierten-eigenen-angaben-zufolge-mit-entlassungen/","belegstufe":"B"},{"bereich":"verteilung","richtung":"vorteil","text":"Von der Anhebung auf 13,90 Euro waren laut Destatis rund 20 % der Jobs von Frauen betroffen (Männer 14 %), in Ostdeutschland rund 20 % (Westdeutschland 16 %).","quelle_url":"https://www.destatis.de/DE/Presse/Pressemitteilungen/2025/07/PD25_256_62.html","belegstufe":"A"}]'::jsonb),
  (6435, 7, 17, null, 'Alle Erwerbstätigen, auch Abgeordnete und Minister, zahlen in die gesetzliche Rente ein', '{701}', 6176, 1, 2, null, 'Mehr Einzahlende verbessern das Verhältnis zu den Rentnern zunächst, später entstehen aus den Beiträgen aber auch Ansprüche; für Beamte kostet der Übergang Bund und Länder anfangs viel Geld. Per Bundesgesetz möglich, mit langen Übergangszeiten.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=23', null, 'gemischt', '2026-09-29', false, true, null, '[]'::jsonb),
  (6436, 7, 17, null, 'Alle Selbstständigen in die Sozialversicherungen einbeziehen', '{702}', 6175, 2, 3, null, 'Viele Solo-Selbstständige sorgen kaum vor und sind im Alter häufiger arm; eine Vorsorgepflicht setzt direkt an dieser Lücke an, wirkt aber erst über Jahrzehnte, und Pflichtbeiträge belasten Selbstständige mit geringem Einkommen. Per Bundesgesetz umsetzbar.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=15', null, 'gemischt', '2026-09-29', false, true, null, '[]'::jsonb),
  (6437, 7, 17, null, 'Mindestlohn sofort auf 15 Euro anheben', '{702}', 6181, 1, 3, null, 'Ein höherer Mindestlohn erhöht die Rentenansprüche von Geringverdienenden; auch mit 15 Euro liegt die Rente nach Lücken im Erwerbsleben oft nahe der Grundsicherung. Per Bundesgesetz umsetzbar, bisher entscheidet die Mindestlohnkommission.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=21', null, 'gemischt', '2026-09-29', false, true, null, '[{"bereich":"wirtschaft","richtung":"nachteil","text":"Auf höhere Lohnkosten reagierten nach der Anhebung auf 12 Euro (2022) 53,4 % der Mindestlohnbetriebe und 72,6 % im Gastgewerbe mit Preiserhöhungen (IAB-Betriebsbefragung).","quelle_url":"https://iab-forum.de/mindestlohnerhoehung-auf-12-euro-nur-wenige-betriebe-reagierten-eigenen-angaben-zufolge-mit-entlassungen/","belegstufe":"B"},{"bereich":"verteilung","richtung":"vorteil","text":"Von der Anhebung auf 13,90 Euro waren laut Destatis rund 20 % der Jobs von Frauen betroffen (Männer 14 %), in Ostdeutschland rund 20 % (Westdeutschland 16 %).","quelle_url":"https://www.destatis.de/DE/Presse/Pressemitteilungen/2025/07/PD25_256_62.html","belegstufe":"A"}]'::jsonb),
  (6438, 7, 17, null, 'Mindestrente von 1.500 Euro nach 40 Versicherungsjahren, gestaffelt nach Versicherungsjahren', '{702}', null, 2, 1, null, 'Eine Mindestrente hebt niedrige Renten nach langen Versicherungszeiten direkt an; wer große Lücken im Erwerbsleben hat, erreicht die Stufen oft nicht. Die Kosten wären hoch, die Finanzierung nennt das Programm nicht.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=22', null, 'gemischt', '2026-09-29', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Die Grundrente kostete laut Gesetzentwurf rund 1,3 Mrd. Euro im Einführungsjahr 2021 für rund 1,3 Mio. Menschen; eine Mindestrente von 1.500 Euro würde mehr kosten.","quelle_url":"https://www.bundestag.de/webarchiv/Ausschuesse/ausschuesse19/a11/Anhoerungen/683366-683366","belegstufe":"A"}]'::jsonb),
  (6439, 7, 17, null, 'Leistungsniveau von mindestens 75 Prozent des früheren Nettoeinkommens', '{701}', null, 1, 1, null, 'Ein deutlich höheres Leistungsniveau erhöht die Renten aller, gleicht aber nur die Folgen des steigenden Verhältnisses von Rentnern zu Beitragszahlenden aus; die Mehrkosten wären sehr hoch und sind nicht geklärt.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=23', null, 'gemischt', '2026-09-29', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Die Haltelinie von 48 % kostet den Bund laut Gesetzentwurf 2029 rund 3,6 und 2031 rund 11,0 Mrd. Euro; ein Niveau von 75 % würde deutlich mehr kosten.","quelle_url":"https://www.ihre-vorsorge.de/rente/nachrichten/stabiles-rentenniveau-kostet-alle-steuerzahler-milliarden-euro","belegstufe":"A"}]'::jsonb);

